"""The TypeScript view of the records: enum-style constants and interfaces for packages/core."""

from __future__ import annotations

from enum import Enum

from pydantic import BaseModel

from ..probe_contracts import Contracts
from .field_types import FieldType, describe, doc_of

HEADER = (
    "// GENERATED by `python -m probe_contracts.codegen` from contracts/probe_contracts/records.\n"
    "// Do not edit: change the record there and rerun.\n"
)

_SCALARS = {
    "uuid": "string",
    "str": "string",
    "int": "number",
    "float": "number",
    "bool": "boolean",
    "datetime": "string",
    "dict": "Record<string, unknown>",
}


def render_type(field_type: FieldType) -> str:
    if field_type.kind == "scalar":
        return _SCALARS[field_type.name]
    if field_type.kind == "optional":
        return f"{render_type(field_type.inner)} | null"
    if field_type.kind == "list":
        item = render_type(field_type.inner)
        return f"({item})[]" if " " in item else f"{item}[]"
    if field_type.kind == "literal":
        return " | ".join(f'"{v}"' for v in field_type.values)
    return field_type.name


def member_key(name: str) -> str:
    """`EVALUATES_ON` -> `EvaluatesOn`: the dashboard's enum-object member style."""
    return "".join(part.capitalize() for part in name.lower().split("_"))


def render_jsdoc(cls: type, indent: str = "") -> str:
    text = doc_of(cls)
    if not text:
        return ""
    lines = text.splitlines()
    if len(lines) == 1:
        return f"{indent}/** {lines[0]} */\n"
    body = "".join(f"{indent} *{' ' + line if line else ''}\n" for line in lines)
    return f"{indent}/**\n{body}{indent} */\n"


def render_enum(cls: type[Enum]) -> str:
    members = "".join(f'  {member_key(m.name)}: "{m.value}",\n' for m in cls)
    name = cls.__name__
    return (
        f"{render_jsdoc(cls)}export const {name} = {{\n{members}}} as const;\n"
        f"export type {name} = (typeof {name})[keyof typeof {name}];\n"
    )


def _interface(cls: type[BaseModel]) -> str:
    fields = "".join(
        f"  {name}: {render_type(describe(info.annotation))};\n" for name, info in cls.model_fields.items()
    )
    return f"{render_jsdoc(cls)}export interface {cls.__name__} {{\n{fields}}}\n"


def render_typescript(contracts: Contracts) -> str:
    blocks = [render_enum(e) for e in contracts.enums]
    blocks += [_interface(m) for m in (*contracts.nested, *contracts.records)]
    return HEADER + "".join(f"\n{block}" for block in blocks)
